begin;

-- Git retains commit-level history but not durable historical push boundaries. Seed the
-- full main timeline once so the platform ledger starts at the repository's first commit.
-- Real GitHub push webhooks take over after this import and remain idempotent by push id.
drop function public.platform_list_development_updates(integer);

create function public.platform_list_development_updates(
  page_limit integer default 100,
  before_pushed_at timestamptz default null,
  before_id uuid default null
)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare bounded_page_limit integer := greatest(1, least(coalesce(page_limit, 100), 100));
begin
  perform private.require_platform_scope('development.read');
  return (
    with candidates as (
      select * from private.development_updates as update_row
      where before_pushed_at is null
        or update_row.pushed_at < before_pushed_at
        or (update_row.pushed_at = before_pushed_at and update_row.id < before_id)
      order by pushed_at desc, id desc
      limit bounded_page_limit + 1
    ), page as (
      select * from candidates
      order by pushed_at desc, id desc
      limit bounded_page_limit
    )
    select jsonb_build_object(
      'items', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', update_row.id, 'github_push_id', update_row.github_push_id,
          'repository_full_name', update_row.repository_full_name,
          'branch_name', update_row.branch_name, 'before_sha', update_row.before_sha,
          'after_sha', update_row.after_sha, 'compare_url', update_row.compare_url,
          'pusher_name', update_row.pusher_name, 'headline', update_row.headline,
          'commits', update_row.commits, 'pushed_at', update_row.pushed_at
        ) order by update_row.pushed_at desc, update_row.id desc)
        from page as update_row
      ), '[]'::jsonb),
      'next_cursor', case when (select count(*) from candidates) > bounded_page_limit then (
        select jsonb_build_object('pushed_at', update_row.pushed_at, 'id', update_row.id)
        from page as update_row
        order by update_row.pushed_at asc, update_row.id asc
        limit 1
      ) else null end
    )
  );
end;
$$;

revoke all on function public.platform_list_development_updates(integer, timestamptz, uuid) from public, anon;
grant execute on function public.platform_list_development_updates(integer, timestamptz, uuid) to authenticated;

